	'messages:config-admin-help' => 'es:Escribe aquí el nombre de usuario que desees, como por ejemplo "Pedro Bloggs".
Este es el nombre que usarás para entrar al wiki.',
	'messages:config-admin-name-blank' => 'es:Escribe un nombre de usuario de administrador.',
