	'messages:apihelp-query+siteinfo-paramvalue-prop-autopromoteonce' => 'en:Returns the automatic promotion configuration that are only done once.',
	'messages:apihelp-query+siteinfo-param-showalldb' => 'en:List all database servers, not just the one lagging the most.',
	'messages:apihelp-query+siteinfo-example-replag' => 'en:Check the current replication lag.',
	'messages:apihelp-query+tokens-summary' => 'en:Gets tokens for data-modifying actions.',
	'messages:apihelp-query+tokens-param-type' => 'en:Types of token to request.',
	'messages:apihelp-query+tokens-example-simple' => 'en:Retrieve a csrf token (the default).',
	'messages:apihelp-query+tokens-example-types' => 'en:Retrieve a watch token and a patrol token.',
