	'messages:apihelp-query+transcludedin-paramvalue-show-!redirect' => 'en:Only show non-redirects.',
	'messages:apihelp-query+usercontribs-param-start' => 'en:The start timestamp to return from, i.e. revisions before this timestamp.',
	'messages:apihelp-query+usercontribs-param-end' => 'en:The end timestamp to return to, i.e. revisions after this timestamp.',
	'messages:apihelp-query+usercontribs-param-iprange' => 'en:The CIDR range to retrieve contributions for. Cannot be used with <var>$1user</var>, <var>$1userprefix</var>, or <var>$1userids</var>.',
	'messages:apihelp-query+usercontribs-paramvalue-prop-autopatrolled' => 'en:Tags autopatrolled edits.',
	'messages:apihelp-query+userinfo-paramvalue-prop-theoreticalratelimits' => 'en:Lists all rate limits that would apply to the current user if they were not exempt from all ratelimits based on user rights or ip.',
	'messages:apihelp-query+userinfo-paramvalue-prop-centralids' => 'en:Adds the central IDs and attachment status for the user.',
	'messages:apihelp-query+userinfo-paramvalue-prop-latestcontrib' => 'en:Adds the date of user\'s latest contribution.',
	'messages:apihelp-query+userinfo-paramvalue-prop-cancreateaccount' => 'en:Indicates whether the user is allowed to create accounts. To check whether some specific account can be created, use [[Special:ApiHelp/query+users|<kbd>action=query&list=users&usprop=cancreate</kbd>]].',
	'messages:apihelp-query+userinfo-param-attachedwiki' => 'en:With <kbd>$1prop=centralids</kbd>, indicate whether the user is attached with the wiki identified by this ID.',
	'messages:apihelp-query+users-paramvalue-prop-groupmemberships' => 'en:Lists groups that each user has been explicitly assigned to, including the expiry date of each group membership.',
	'messages:apihelp-query+users-paramvalue-prop-centralids' => 'en:Adds the central IDs and attachment status for the user.',
	'messages:apihelp-query+users-param-attachedwiki' => 'en:With <kbd>$1prop=centralids</kbd>, indicate whether the user is attached with the wiki identified by this ID.',
